// The golden run and its four terminal views are generated by `bun run golden`, from a run of the fixture repository's
// ticket-to-pr on FAKE-1. This test fails while either is stale: it generates a fresh run and compares it with the
// committed one, the same files and each byte for byte, and renders the views afresh. One field is the machine's:
// `run.json`'s `sail.runtime`, the Bun that generated, which is compared as `bun <version>`.
import { afterAll, beforeAll, expect, test } from 'bun:test';
import { cpSync, existsSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, relative } from 'node:path';
import { GOLDEN_RUN_ID, generateGoldenRun, renderView, VERBOSITIES } from '../../scripts/golden';
import { readEvents } from '../../src/events/consumers/ndjson';

const fixtures = join(import.meta.dir, '..', 'fixtures');
const committed = join(fixtures, 'runs', GOLDEN_RUN_ID);
const temp = mkdtempSync(join(tmpdir(), 'sail-golden-fresh-'));
const fresh = join(temp, 'fresh');

/** Why the fresh run couldn't be generated: each test then fails on what the fresh run lacks, not on the hook. */
let unmade = '';
beforeAll(async () => {
  try {
    await generateGoldenRun(fresh);
  } catch (error) {
    unmade = error instanceof Error ? error.message : String(error);
  }
});
afterAll(() => rmSync(temp, { recursive: true, force: true }));

const REGENERATE = 'run bun run golden';
const RUNTIME = /"runtime": "bun \d+\.\d+\.\d+[^"]*"/;

/** Every file under `dir`, relative to it, sorted: none when the directory isn't there. */
function filesIn(dir: string): string[] {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { recursive: true, withFileTypes: true })
    .filter((entry) => entry.isFile())
    .map((entry) => relative(dir, join(entry.parentPath, entry.name)))
    .sort();
}

/** A file's bytes as text, with the one field that names the machine's Bun put aside. */
const comparable = (dir: string, file: string): string =>
  readFileSync(join(dir, file), 'utf8').replace(RUNTIME, '"runtime": "bun <version>"');

/**
 * Every way the run directory `stored` is not the run `generated`: a file one has and the other lacks, or a file whose
 * bytes differ. Each names the file, and says how to bring the stored run up to date.
 */
function stale(generated: string, stored: string): string[] {
  const [made, kept] = [filesIn(generated), filesIn(stored)];
  return [
    ...made.filter((file) => !kept.includes(file)).map((file) => `${file} is missing: ${REGENERATE}`),
    ...kept.filter((file) => !made.includes(file)).map((file) => `${file} is no file of a fresh run: ${REGENERATE}`),
    ...made
      .filter((file) => kept.includes(file) && comparable(generated, file) !== comparable(stored, file))
      .map((file) => `${file} is stale: ${REGENERATE}`),
  ];
}

/** A copy of the committed golden run, changed by `change`. */
function changedCopy(name: string, change: (dir: string) => void): string {
  const dir = join(temp, name);
  cpSync(committed, dir, { recursive: true });
  change(dir);
  return dir;
}

test('the committed golden run is what a fresh run of the fixture writes: the same files, each byte for byte', () => {
  expect(unmade).toBe('');
  expect(stale(fresh, committed)).toEqual([]);
  expect(filesIn(committed)).toHaveLength(63);
});

test("run.json's sail.runtime is the one field compared apart: a fresh run names the running Bun, and the committed one a Bun", () => {
  const runtimeOf = (dir: string): unknown =>
    existsSync(join(dir, 'run.json')) ? JSON.parse(readFileSync(join(dir, 'run.json'), 'utf8')).sail.runtime : null;
  expect(runtimeOf(fresh)).toBe(`bun ${Bun.version}`);
  expect(runtimeOf(committed)).toMatch(/^bun \d+\.\d+\.\d+/);
  // Nothing else is put aside: a version of sail's own that differs is a difference.
  const bumped = changedCopy('bumped', (dir) => {
    const header = readFileSync(join(dir, 'run.json'), 'utf8');
    writeFileSync(join(dir, 'run.json'), header.replace('"version": "0.0.0"', '"version": "0.0.1"'));
  });
  expect(stale(fresh, bumped)).toEqual([`run.json is stale: ${REGENERATE}`]);
});

test.each<[string, (dir: string) => void, string]>([
  [
    'one byte changed',
    (dir) => {
      const file = join(dir, '03-tests', 'call-2', 'stdout.log');
      writeFileSync(file, readFileSync(file, 'utf8').replace('7 pass', '8 pass'));
    },
    '03-tests/call-2/stdout.log is stale',
  ],
  [
    'one event changed by a millisecond',
    (dir) => {
      const file = join(dir, 'events.ndjson');
      writeFileSync(file, readFileSync(file, 'utf8').replace('T09:00:00.700Z', 'T09:00:00.701Z'));
    },
    'events.ndjson is stale',
  ],
  [
    'one file removed',
    (dir) => rmSync(join(dir, '05-publish', 'call-1', 'steps', '2-open', 'port-events.ndjson')),
    '05-publish/call-1/steps/2-open/port-events.ndjson is missing',
  ],
  [
    'one file added',
    (dir) => writeFileSync(join(dir, '05-publish', 'call-1', 'notes.md'), ''),
    '05-publish/call-1/notes.md is no file of a fresh run',
  ],
])('a golden run with %s is stale: the comparison names the file and says to regenerate', (how, change, problem) => {
  expect(stale(fresh, changedCopy(how.replaceAll(' ', '-'), change))).toEqual([`${problem}: ${REGENERATE}`]);
});

test.each(VERBOSITIES.map((verbosity) => [verbosity] as const))(
  "the committed %s view is the golden run's events rendered afresh, byte for byte",
  (verbosity) => {
    const view = readFileSync(join(fixtures, 'terminal', `${verbosity}.txt`), 'utf8');
    expect(renderView(readEvents(committed), verbosity)).toBe(view);
    expect(view).toStartWith(`sail · ticket-to-pr v1 · ${GOLDEN_RUN_ID}\n`);
  },
);

test('a view rendered from a changed stream differs from the committed one: a stale view fails this test', () => {
  const events = readEvents(committed).filter((event) => event.type !== 'loop:exit');
  const committedView = readFileSync(join(fixtures, 'terminal', 'normal.txt'), 'utf8');
  const rendered = renderView(events, 'normal');
  expect(rendered).not.toBe(committedView);
  expect(committedView.replace('fix                 ↻ break after 2/3\n', '')).toBe(rendered);
});

test('no file of a fresh run holds the path of the temporary repository it ran in, or of this checkout', () => {
  const files = filesIn(fresh);
  expect(files).toHaveLength(63);
  const machine = [tmpdir(), 'sail-golden-', join(import.meta.dir, '..', '..')];
  const holding = files.filter((file) =>
    machine.some((path) => readFileSync(join(fresh, file), 'utf8').includes(path)),
  );
  expect(holding).toEqual([]);
});

test('every file of a fresh run is an ordinary, writable file: run.json too, which the run itself leaves read-only', () => {
  const files = filesIn(fresh);
  expect(files).toHaveLength(63);
  expect(files.filter((file) => (statSync(join(fresh, file)).mode & 0o200) === 0)).toEqual([]);
});
